node -e '
const fs = require("fs");
const regions = ["north", "south", "east", "west"];
const out = { regions: {}, grand_units: 0, grand_weighted: 0 };
for (const r of regions) {
  const rows = JSON.parse(fs.readFileSync(r + ".json", "utf8"));
  if (!Array.isArray(rows)) throw new Error(r + ".json is not a JSON array");
  for (const row of rows) {
    if (typeof row.units !== "number" || typeof row.weight !== "number") {
      throw new Error(r + ".json has a record without numeric units/weight");
    }
  }
  const count = rows.length;
  const units = rows.reduce((a, x) => a + x.units, 0);
  const weighted = rows.reduce((a, x) => a + x.units * x.weight, 0);
  out.regions[r] = { count, units, weighted };
  out.grand_units += units;
  out.grand_weighted += weighted;
}
fs.writeFileSync("answer.json", JSON.stringify(out, null, 2) + "\n");
console.log("wrote answer.json");
console.log(fs.readFileSync("answer.json", "utf8"));
'

cd /tmp/neutrino-fast-live-b4eG5i/parallel_analysis/standard/0 && node <<'EOF'
const fs = require('fs');
const dir = '/tmp/neutrino-fast-live-b4eG5i/parallel_analysis/standard/0';
const names = ['north', 'south', 'east', 'west'];
// Read-only inspector claims recorded in steps 2-5
const claims = {
  north: { count: 10, units: 90,  weighted: 167 },
  south: { count: 10, units: 94,  weighted: 171 },
  east:  { count: 10, units: 98,  weighted: 209 },
  west:  { count: 10, units: 85,  weighted: 145 }
};
let ok = true;
const check = (label, pass, detail) => {
  console.log((pass ? 'PASS  ' : 'FAIL  ') + label + (detail !== undefined ? '  ' + detail : ''));
  if (!pass) ok = false;
};

// 1. source completeness
const missing = names.filter(n => !fs.existsSync(`${dir}/${n}.json`));
check('source completeness: north/south/east/west all present', missing.length === 0,
      missing.length ? 'missing: ' + missing.join(',') : '4/4 files');

const answer = JSON.parse(fs.readFileSync(`${dir}/answer.json`, 'utf8'));

// 2. shape of answer.json
const topKeys = Object.keys(answer).sort();
check('top-level keys exactly grand_units, grand_weighted, regions',
      JSON.stringify(topKeys) === JSON.stringify(['grand_units', 'grand_weighted', 'regions']),
      JSON.stringify(topKeys));
const regionKeys = Object.keys(answer.regions).sort();
check('regions keyed exactly north/south/east/west (no extras, none missing)',
      JSON.stringify(regionKeys) === JSON.stringify(names.slice().sort()),
      JSON.stringify(regionKeys));

// 3. per-region: exact fields, integer types, recompute, inspector agreement
const recomputed = {};
for (const name of names) {
  const rows = JSON.parse(fs.readFileSync(`${dir}/${name}.json`, 'utf8'));
  let count = rows.length, units = 0, weighted = 0;
  for (const r of rows) { units += r.units; weighted += r.units * r.weight; }
  recomputed[name] = { count, units, weighted };

  const got = answer.regions[name];
  const fields = Object.keys(got).sort();
  check(`${name}: entry fields exactly count, units, weighted`,
        JSON.stringify(fields) === JSON.stringify(['count', 'units', 'weighted']), JSON.stringify(fields));
  check(`${name}: all values are integers`,
        Number.isInteger(got.count) && Number.isInteger(got.units) && Number.isInteger(got.weighted),
        `${got.count}/${got.units}/${got.weighted}`);
  check(`${name}: count/units/weighted equal fresh Node recompute of ${name}.json`,
        got.count === count && got.units === units && got.weighted === weighted,
        `answer=${got.count}/${got.units}/${got.weighted} recompute=${count}/${units}/${weighted}`);
  const c = claims[name];
  check(`${name}: equals independent inspector report`,
        got.count === c.count && got.units === c.units && got.weighted === c.weighted,
        `answer=${got.count}/${got.units}/${got.weighted} inspector=${c.count}/${c.units}/${c.weighted}`);
}

// 4. grand totals, arithmetic and cross-source agreement
const sumUnits = names.reduce((s, n) => s + recomputed[n].units, 0);
const sumWeighted = names.reduce((s, n) => s + recomputed[n].weighted, 0);
const claimUnits = names.reduce((s, n) => s + claims[n].units, 0);
const claimWeighted = names.reduce((s, n) => s + claims[n].weighted, 0);
check('grand_units = sum of the four recomputed regions', answer.grand_units === sumUnits, `${answer.grand_units} vs ${sumUnits}`);
check('grand_weighted = sum of the four recomputed regions', answer.grand_weighted === sumWeighted, `${answer.grand_weighted} vs ${sumWeighted}`);
check('grand_units = sum of four inspector reports', answer.grand_units === claimUnits, `${answer.grand_units} vs ${claimUnits}`);
check('grand_weighted = sum of four inspector reports', answer.grand_weighted === claimWeighted, `${answer.grand_weighted} vs ${claimWeighted}`);
check('grand_units is integer', Number.isInteger(answer.grand_units), String(answer.grand_units));
check('grand_weighted is integer', Number.isInteger(answer.grand_weighted), String(answer.grand_weighted));

console.log('\nsummary: ' + (ok
  ? 'ALL CHECKS PASSED — answer.json matches fresh Node recompute, all four inspector reports, and all four sources are present'
  : 'AT LEAST ONE CHECK FAILED'));
process.exit(ok ? 0 : 1);
EOF
